#!/usr/bin/env python3
"""Copy the manuscript files generated by the artifact into a paper's results directory.

The artifact never writes outside its own tree. An author who keeps the manuscript
next to the artifact runs this script to refresh it from the regenerated release.
"""

from __future__ import annotations

import argparse
import shutil
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[1]
RELEASE = PROJECT_ROOT / "release"

# Manuscript file name -> generated source inside the release tree.
MANUSCRIPT_FILES = {
    "paper_macros.tex": RELEASE / "paper_macros.tex",
    "linux_discovery_macros.tex": RELEASE / "linux_discovery_macros.tex",
    "fidelity_macros.tex": RELEASE / "fidelity_macros.tex",
    "fidelity_table.tex": RELEASE / "experiments" / "fidelity_rationale" / "fidelity_rationale.tex",
    "baseline_table.tex": RELEASE / "experiments" / "enrichment_baseline" / "baseline_table.tex",
    "commitments_table.tex": RELEASE / "experiments" / "execution_commitments" / "commitments_table.tex",
    "provenance_table.tex": RELEASE / "experiments" / "provenance" / "provenance_table.tex",
    "campaign_summary_table.tex": RELEASE / "experiments" / "campaign_summary" / "campaign_summary_table.tex",
    "claim_ledger_table.tex": RELEASE / "claims" / "claim_ledger_table.tex",
}


def sync(paper_results: Path) -> list[Path]:
    """Copy every generated manuscript file and return the written paths."""
    paper_results.mkdir(parents=True, exist_ok=True)
    written = []
    for name, source in MANUSCRIPT_FILES.items():
        destination = paper_results / name
        shutil.copyfile(source, destination)
        written.append(destination)
    return written


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("paper_results", type=Path, help="the manuscript's results directory")
    args = parser.parse_args()
    for path in sync(args.paper_results):
        print(f"[sync-paper] wrote {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
